text:
{{
  (() => {
    const documento = String(inpCpCedulaConductor.text || "").trim();
    const conductor = appsmith.store.cp_ui_conductor_estado_operativo;

    if (!documento) return "";

    if (!conductor?.conductor_id) {
      return "⚪ CONDUCTOR NUEVO";
    }

    const dias = Number(conductor.dias_vigencia_licencia);

    if (
      conductor.activo === false ||
      conductor.estado_administrativo !== "ACTIVO"
    ) {
      return "🔴 CONDUCTOR INACTIVO";
    }

    if (conductor.disponible_para_viaje === false) {
      return "🔴 CONDUCTOR NO APTO PARA VIAJE";
    }

    if (Number.isFinite(dias) && dias < 0) {
      return `🔴 LICENCIA VENCIDA HACE ${Math.abs(dias)} ${
        Math.abs(dias) === 1 ? "DÍA" : "DÍAS"
      }`;
    }

    if (dias === 0) {
      return "🟠 LICENCIA VENCE HOY";
    }

    if (dias === 1) {
      return "🟠 LICENCIA VENCE MAÑANA";
    }

    if (Number.isFinite(dias) && dias <= 30) {
      return `🟠 LICENCIA VENCE EN ${dias} DÍAS`;
    }

    if (Number.isFinite(dias) && dias <= 90) {
      return `🟡 LICENCIA VENCE EN ${dias} DÍAS`;
    }

    return "🟢 CONDUCTOR APTO PARA VIAJE";
  })()
}}

textColor:
{{
  (() => {
    const documento = String(inpCpCedulaConductor.text || "").trim();
    const conductor = qCpBuscarConductorPorDocumento.data?.[0];

    if (!documento || !conductor?.conductor_id) {
      return "#5F6368";
    }

    const dias = Number(conductor.dias_vigencia_licencia);

    if (
      conductor.activo === false ||
      conductor.estado_administrativo !== "ACTIVO" ||
      conductor.disponible_para_viaje === false ||
      (Number.isFinite(dias) && dias < 0)
    ) {
      return "#C62828";
    }

    if (Number.isFinite(dias) && dias <= 30) {
      return "#E65100";
    }

    if (Number.isFinite(dias) && dias <= 90) {
      return "#9A6700";
    }

    return "#2E7D32";
  })()
}}
